  ('hi', 'whatsNew.item.readableCode.detail', $json$"जवाबों में कोड प्रकार के अनुसार रंगीन होता है (कीवर्ड, स्ट्रिंग, संख्या, टिप्पणी), गहरी पृष्ठभूमि पर दिखता है और पंक्ति संख्याएँ अलग हाशिये में होती हैं; लंबे ब्लॉक सिमटे हुए खुलते हैं। फ़ाइल पथ, बिना बैकटिक के लिखे होने पर भी, एक बैज बन जाते हैं जिसमें फ़ोल्डर हल्का और फ़ाइल का नाम उभरा होता है।"$json$::jsonb),
