  ('ru', 'whatsNew.item.readableCode.detail', $json$"Код в ответах раскрашен по типу (ключевые слова, строки, числа, комментарии), лежит на более глубоком фоне, номера строк вынесены на отдельное поле, а длинные блоки открываются свёрнутыми. Пути к файлам, даже без обратных кавычек, превращаются в метку с приглушённой папкой и выделенным именем файла."$json$::jsonb),
